//! `tables [--check]`: write (or check) the constant tables of the elementary functions
//! (`liella_mathtools::tables`, D-10.3), one `@generated` file per family in
//! `crates/math/src/coeffs/`.
//!
//! Writing touches only the files whose contents changed, so a family's generator change
//! rewrites (and rebuilds) only its own file. `--check` (run by `cargo xtask static`)
//! regenerates every file in memory and compares it with the tree: a stale or hand-edited
//! file, a missing one, or a leftover file that still carries this generator's header fails,
//! naming the file.

#![allow(clippy::disallowed_methods)] // a host tool: S8 governs the library crates only

use std::path::Path;
use std::process::ExitCode;

/// The first line of every file this tool writes.
const HEADER: &str = "// @generated by `cargo xtask tables`";

fn main() -> ExitCode {
    let check = std::env::args().any(|a| a == "--check");
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../math/src/coeffs");
    let files = liella_mathtools::tables::generate();
    let mut bad = false;
    for (name, src) in &files {
        let path = dir.join(name);
        let old = std::fs::read_to_string(&path).ok();
        if old.as_deref() == Some(src.as_str()) {
            continue;
        }
        if check {
            let why = if old.is_some() { "is out of date (stale or edited by hand)" } else { "is missing" };
            eprintln!("tables: crates/math/src/coeffs/{name} {why}: run `cargo xtask tables`");
            bad = true;
        } else if let Err(e) = std::fs::write(&path, src) {
            eprintln!("tables: {}: {e}", path.display());
            return ExitCode::FAILURE;
        } else {
            println!("tables: wrote crates/math/src/coeffs/{name}");
        }
    }
    // A generated file this generator no longer writes (a family renamed, or the single-file
    // layout's tables.rs brought back by a merge) is a leftover: report it in both modes.
    let mut extra: Vec<String> = std::fs::read_dir(&dir)
        .map(|d| d.flatten().filter_map(|e| e.file_name().into_string().ok()).collect())
        .unwrap_or_default();
    extra.sort();
    for name in extra {
        let generated = std::fs::read_to_string(dir.join(&name)).is_ok_and(|s| s.starts_with(HEADER));
        if generated && !files.iter().any(|(f, _)| *f == name) {
            eprintln!("tables: crates/math/src/coeffs/{name} is a leftover generated file that `cargo xtask tables` no longer writes: remove it");
            bad = true;
        }
    }
    if bad {
        return ExitCode::FAILURE;
    }
    if check {
        println!("tables: up to date ({} files)", files.len());
    }
    ExitCode::SUCCESS
}
